import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor max_reduce_forward(torch::Tensor x, int64_t dim);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
#include <float.h>
#include <vector>
constexpr int STREAM_TX = 512;
constexpr int STREAM_CHUNKS = 8;
// Each block sweeps one contiguous [rows x inner] region sequentially in memory.
// Threads cover STREAM_TX consecutive floats per step (fully coalesced), and each
// thread keeps STREAM_CHUNKS register accumulators so a whole 4096-float group of
// the inner dimension is reduced per pass. The reduce dimension is split across
// blocks (partial buffer + tiny combine kernel) so the grid can fill the GPU even
// when outer is small. This turns the previous strided column-slab reads into pure
// sequential DRAM streams, which is the right shape for this memory-bound reduction.
__global__ void max_reduce_stream_kernel(
    const float* __restrict__ x,
    float* __restrict__ dst,
    long long outer,
    long long reduce,
    long long inner,
    int split,
    long long rows_per_split)
{
    const long long group_stride = (long long)STREAM_TX * STREAM_CHUNKS;
    const long long num_groups = (inner + group_stride - 1) / group_stride;
    const long long per_outer = (long long)split * num_groups;
    const long long total_units = outer * per_outer;
    const long long step = (long long)gridDim.x;
    const int tx = threadIdx.x;
    for (long long unit = blockIdx.x; unit < total_units; unit += step) {
        const long long o = unit / per_outer;
        const long long rem = unit - o * per_outer;
        const long long s = rem / num_groups;
        const long long g = rem - s * num_groups;
        const long long r0 = s * rows_per_split;
        long long r1 = r0 + rows_per_split;
        if (r1 > reduce) r1 = reduce;
        const long long nrows = r1 - r0;
        const long long i_base = g * group_stride + tx;
        const float* xp = x + (o * reduce + r0) * inner + i_base;
        float* wp = dst + (s * outer + o) * inner + i_base;
        float m[STREAM_CHUNKS];
        #pragma unroll
        for (int c = 0; c < STREAM_CHUNKS; ++c) m[c] = -FLT_MAX;
        if ((g + 1) * group_stride <= inner) {
            for (long long r = 0; r < nrows; ++r) {
                const float* p = xp + r * inner;
                #pragma unroll
                for (int c = 0; c < STREAM_CHUNKS; ++c)
                    m[c] = fmaxf(m[c], __ldg(p + (long long)c * STREAM_TX));
            }
            #pragma unroll
            for (int c = 0; c < STREAM_CHUNKS; ++c)
                wp[(long long)c * STREAM_TX] = m[c];
        } else {
            for (long long r = 0; r < nrows; ++r) {
                const float* p = xp + r * inner;
                #pragma unroll
                for (int c = 0; c < STREAM_CHUNKS; ++c) {
                    if (i_base + (long long)c * STREAM_TX < inner)
                        m[c] = fmaxf(m[c], __ldg(p + (long long)c * STREAM_TX));
                }
            }
            #pragma unroll
            for (int c = 0; c < STREAM_CHUNKS; ++c) {
                if (i_base + (long long)c * STREAM_TX < inner)
                    wp[(long long)c * STREAM_TX] = m[c];
            }
        }
    }
}
__global__ void max_reduce_combine_kernel(
    const float* __restrict__ partial,
    float* __restrict__ out,
    long long total_out,
    int split)
{
    const long long step = (long long)gridDim.x * blockDim.x;
    for (long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
         idx < total_out; idx += step) {
        float m = -FLT_MAX;
        for (int s = 0; s < split; ++s)
            m = fmaxf(m, __ldg(partial + (long long)s * total_out + idx));
        out[idx] = m;
    }
}
static long long max_reduce_wave_blocks(int threads) {
    int device = 0;
    C10_CUDA_CHECK(cudaGetDevice(&device));
    int sm_count = 0;
    C10_CUDA_CHECK(cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device));
    int blocks_per_sm = 0;
    C10_CUDA_CHECK(cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &blocks_per_sm, (const void*)max_reduce_stream_kernel, threads, 0));
    if (blocks_per_sm < 1) blocks_per_sm = 1;
    if (sm_count < 1) sm_count = 1;
    return (long long)sm_count * (long long)blocks_per_sm;
}
torch::Tensor max_reduce_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "only float32 is supported");
    const at::cuda::OptionalCUDAGuard guard(x.device());
    auto y = x.contiguous();
    int64_t ndim = y.dim();
    TORCH_CHECK(ndim >= 1, "x must have at least one dimension");
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto sizes = y.sizes().vec();
    TORCH_CHECK(sizes[dim] > 0, "cannot reduce over an empty dimension");
    long long outer = 1;
    for (int64_t d = 0; d < dim; ++d) outer *= sizes[d];
    long long reduce = sizes[dim];
    long long inner = 1;
    for (int64_t d = dim + 1; d < ndim; ++d) inner *= sizes[d];
    std::vector<int64_t> out_sizes = sizes;
    out_sizes.erase(out_sizes.begin() + dim);
    auto out = at::empty(out_sizes, y.options());
    long long total_out = outer * inner;
    if (total_out == 0) return out;
    auto stream = at::cuda::getCurrentCUDAStream();
    const int threads = STREAM_TX;
    const long long wave = max_reduce_wave_blocks(threads);
    long long split = 1;
    if (outer < wave) {
        split = wave / outer;
        if (split > reduce) split = reduce;
        if (split > 64) split = 64;
        if (split < 1) split = 1;
    }
    long long rows_per_split = (reduce + split - 1) / split;
    split = (reduce + rows_per_split - 1) / rows_per_split;
    const long long group_stride = (long long)STREAM_TX * STREAM_CHUNKS;
    const long long num_groups = (inner + group_stride - 1) / group_stride;
    const long long total_units = outer * split * num_groups;
    long long blocks_ll = total_units < wave ? total_units : wave;
    if (blocks_ll < 1) blocks_ll = 1;
    dim3 blocks((unsigned int)blocks_ll);
    if (split == 1) {
        max_reduce_stream_kernel<<<blocks, threads, 0, stream>>>(
            y.data_ptr<float>(), out.data_ptr<float>(), outer, reduce, inner,
            1, rows_per_split);
    } else {
        auto partial = at::empty({split * total_out}, y.options());
        max_reduce_stream_kernel<<<blocks, threads, 0, stream>>>(
            y.data_ptr<float>(), partial.data_ptr<float>(), outer, reduce, inner,
            (int)split, rows_per_split);
        const int cthreads = 256;
        long long cblocks = (total_out + cthreads - 1) / cthreads;
        const long long ccap = wave * 4;
        if (cblocks > ccap) cblocks = ccap;
        if (cblocks < 1) cblocks = 1;
        max_reduce_combine_kernel<<<dim3((unsigned int)cblocks), cthreads, 0, stream>>>(
            partial.data_ptr<float>(), out.data_ptr<float>(), total_out, (int)split);
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
"""

_ext = load_inline(
    name="max_reduce_dim_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["max_reduce_forward"],
    verbose=False,
)


class Model(nn.Module):
    def __init__(self, dim: int):
        super(Model, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return torch.max(x, dim=self.dim)[0]


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.is_cuda and x.dtype == torch.float32:
            return _ext.max_reduce_forward(x, self.dim)
        return torch.max(x, dim=self.dim)[0]

